  String fmt(int s){final h=s~/3600,m=(s%3600)~/60,sec=s%60;return h>0?'${h.toString().padLeft(2,'0')}:${m.toString().padLeft(2,'0')}:${sec.toString().padLeft(2,'0')}':'${m.toString().padLeft(2,'0')}:${sec.toString().padLeft(2,'0')}';}
